"""Build command evidence and a compact appendix; never write the primary report.

Run only when the parent's command journal is current, for example:
  .venv/bin/python sf-nr-b1/build_report.py \
    --artifact docs/reports/2026-11-12-notify-rebase-commands.json \
    --appendix sf-nr-b1/command-appendix.md

The JSON retains the exact journal, complete agent audit Markdown, and helper
sources. Markdown abbreviates long stdin bodies and repeated failure output,
with explicit JSON locations for the full evidence. Session polls are attached
to their originating command when a session ID is available.
"""
from __future__ import annotations

import argparse
import html
import json
from pathlib import Path
import re
from typing import Any


WORKTREE = Path(__file__).resolve().parent.parent
BACKTICK = chr(96)


def job_path(value: str | Path) -> Path:
    path = Path(value)
    if not path.is_absolute():
        path = WORKTREE / path
    path = path.resolve()
    if path != WORKTREE and WORKTREE not in path.parents:
        raise ValueError(f"Path outside assigned workspace: {path}")
    return path


def relative(path: Path) -> str:
    return str(path.relative_to(WORKTREE))


def journal_entries(value: Any, locator: str = "root_journal"):
    if isinstance(value, list):
        for index, item in enumerate(value):
            yield f"{locator}[{index}]", item
    elif isinstance(value, dict):
        for key in ("commands", "entries", "journal", "events", "records"):
            if isinstance(value.get(key), list):
                yield from journal_entries(value[key], f"{locator}.{key}")
                return
        if any(key in value for key in ("cmd", "command", "tool", "tool_name")):
            yield locator, value
        else:
            for key, item in value.items():
                if isinstance(item, (list, dict)):
                    yield from journal_entries(item, f"{locator}[{json.dumps(key)}]")


def find_command(entry: Any) -> str | None:
    if isinstance(entry, str):
        return entry
    if not isinstance(entry, dict):
        return None
    for key in ("cmd", "command", "shell_command"):
        if isinstance(entry.get(key), str):
            return entry[key]
    for key in ("args", "arguments", "input", "request", "call", "parameters"):
        nested = entry.get(key)
        if isinstance(nested, str):
            try:
                nested = json.loads(nested)
            except ValueError:
                continue
        if isinstance(nested, dict):
            result = find_command(nested)
            if result:
                return result
    return None


def result_of(entry: Any) -> Any:
    if not isinstance(entry, dict):
        return entry
    for key in ("result", "response", "tool_result"):
        if key in entry:
            value = entry[key]
            if isinstance(value, str):
                try:
                    return json.loads(value)
                except ValueError:
                    return {"output": value}
            return value
    return entry


def find_field(value: Any, names: tuple[str, ...]) -> Any:
    if isinstance(value, dict):
        for name in names:
            if name in value and value[name] is not None:
                return value[name]
        for key in ("args", "arguments", "input", "request", "result", "response", "tool_result", "value"):
            found = find_field(value.get(key), names)
            if found is not None:
                return found
    return None


def output_text(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        pieces = []
        if isinstance(value.get("value"), dict):
            return output_text(value["value"])
        for key in ("output", "stdout", "stderr", "text", "message"):
            if isinstance(value.get(key), str):
                pieces.append(value[key])
        if not pieces and isinstance(value.get("content"), list):
            pieces.extend(output_text(item) for item in value["content"])
        return "\n".join(pieces)
    if isinstance(value, list):
        return "\n".join(output_text(item) for item in value)
    return ""


def compact(value: str, limit: int = 220) -> str:
    value = re.sub(r"\s+", " ", value).strip()
    return value if len(value) <= limit else value[: limit - 1] + "…"


def outcome_summary(result: Any, *, initial: Any = None) -> str:
    exit_code = find_field(result, ("exit_code", "returncode", "return_code"))
    if exit_code is None:
        exit_code = find_field(initial, ("exit_code", "returncode", "return_code"))
    session_id = find_field(result, ("session_id", "cell_id"))
    lines = [line.strip() for line in output_text(result).splitlines() if line.strip()]
    signals = re.compile(
        r"\b\d+ (?:passed|failed|errors?|skipped|deselected|xfailed|xpassed)\b|"
        r"Successfully rebased|CONFLICT|HEAD is now|Resolved \d+ packages|"
        r"Installed \d+ packages|Audited \d+ packages|syntax OK|"
        r"Clause order unchanged|Ledger parses|^fatal:|^error:|^ERROR:"
    )
    notable = [line for line in lines if signals.search(line)]
    detail = compact("; ".join(notable[-2:])) if notable else compact(lines[-1] if lines else "")
    status = f"exit {exit_code}" if exit_code is not None else (
        f"running/session {session_id}" if session_id is not None else "exit not recorded"
    )
    return status + ("; " + detail if detail else "")


def command_label(command: str) -> str:
    lines = [line.strip() for line in command.splitlines() if line.strip()]
    if len(lines) <= 1 and len(command) <= 180:
        return command.strip()
    executable = next((line for line in lines if re.search(
        r"(?:run_pytest\.py|\bpytest\b|\buv (?:sync|pip)\b|\bgit rebase\b)", line
    ) and not line.startswith(("import ", "from ", "#"))), None)
    if executable:
        return compact(executable, 170) + f" [script: {len(lines)} nonempty lines]"
    first = lines[0] if lines else "(empty command)"
    return compact(first, 150) + f" [full invocation: {len(lines)} nonempty lines]"


def normalize_journal(journal: Any) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    records: list[dict[str, Any]] = []
    sessions: dict[str, dict[str, Any]] = {}
    unattached = []
    for locator, entry in journal_entries(journal):
        command = find_command(entry)
        tool = str(find_field(entry, ("tool", "tool_name", "name", "kind")) or "")
        poll = any(word in tool.lower() for word in ("write_stdin", "poll", "wait")) or bool(
            command and (command.startswith("poll ") or "; poll " in command)
        )
        result = result_of(entry)
        session_id = find_field(entry, ("session_id", "cell_id"))
        if session_id is None:
            session_id = find_field(result, ("session_id", "cell_id"))
        if session_id is None and poll and command:
            matched = re.search(r"session\s+(\d+)", command)
            if matched:
                session_id = matched.group(1)
        if command and not poll:
            record = {"id": f"R{len(records) + 1:03d}", "command": command,
                      "journal_location": locator, "completion_locations": [],
                      "result_summary": outcome_summary(result),
                      "_initial": result, "_latest": result}
            records.append(record)
            if session_id is not None:
                sessions[str(session_id)] = record
        elif session_id is not None and str(session_id) in sessions:
            record = sessions[str(session_id)]
            record["completion_locations"].append(locator)
            record["_latest"] = result
            record["result_summary"] = outcome_summary(result, initial=record["_initial"])
        elif poll or not command:
            unattached.append({"journal_location": locator,
                               "result_summary": outcome_summary(result)})
    for record in records:
        record.pop("_initial", None)
        record.pop("_latest", None)
    return records, unattached


def audit_items(markdown: str) -> list[dict[str, str]]:
    # Preserve the complete source separately, even for inventories whose
    # formatting cannot safely be reduced to numbered command/result pairs.
    lines = markdown.splitlines()
    headings = [i for i, line in enumerate(lines)
                if line.startswith("#") and re.search(r"command|inventory", line, re.I)]
    if headings:
        lines = lines[headings[-1] + 1:]
    starts = [i for i, line in enumerate(lines) if re.match(r"^\s*\d+[.)]\s+", line)]
    items = []
    for position, start in enumerate(starts):
        end = starts[position + 1] if position + 1 < len(starts) else len(lines)
        block = lines[start:end]
        command = re.sub(r"^\s*\d+[.)]\s+", "", block[0]).strip(BACKTICK + " ")
        result_lines = [re.sub(r"^\s*(?:Result|Outcome)\s*:\s*", "", line, flags=re.I)
                        for line in block if re.match(r"^\s*(?:Result|Outcome)\s*:", line, re.I)]
        result = compact(" ".join(result_lines)) if result_lines else "See complete inventory in JSON"
        items.append({"command_label": compact(command, 180), "result_summary": result})
    return items


def cell(text: str) -> str:
    return html.escape(text).replace("|", "&#124;")


def make_appendix(artifact_path: Path, records, audits, unattached) -> str:
    link = f"[{artifact_path.name}]({artifact_path.name})"
    out = ["Command evidence: " + link + ". Exact shell invocations and results are preserved in "
           + BACKTICK + "root_journal" + BACKTICK + "; the table IDs map to "
           + BACKTICK + "root_commands" + BACKTICK + ". Agent inventories and job helper sources "
           "are preserved in full in the same artifact. Long stdin bodies and repeated failures "
           "are abbreviated here.", "", "| ID | Command | Result |", "| --- | --- | --- |"]
    for record in records:
        out.append(f"| {record['id']} | <code>{cell(command_label(record['command']))}</code> "
                   f"| {cell(record['result_summary'])} |")
    for audit_index, audit in enumerate(audits):
        out.extend(["", f"Agent A{audit_index + 1}: {audit['path']}; exact inventory and results: "
                    + BACKTICK + f"agent_audits[{audit_index}].markdown" + BACKTICK + "."])
        items = audit_items(audit["markdown"])
        if items:
            out.extend(["", "| ID | Command | Result |", "| --- | --- | --- |"])
            for index, item in enumerate(items, 1):
                out.append(f"| A{audit_index + 1}.{index:02d} | <code>{cell(item['command_label'])}</code> "
                           f"| {cell(item['result_summary'])} |")
        else:
            out.append("The original audit formatting is retained verbatim in the JSON artifact.")
    if unattached:
        out.extend(["", f"{len(unattached)} tool-only events without an identifiable originating "
                    "session are retained in the exact journal; see " + BACKTICK
                    + "unattached_tool_events" + BACKTICK + " for final outcome summaries."])
    return "\n".join(out) + "\n"


def write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".sf-nr-b1-tmp")
    temporary.write_text(text, encoding="utf-8")
    temporary.replace(path)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--journal", default="sf-nr-b1/root-command-journal.json")
    parser.add_argument("--audit", action="append", help="Repeat for exact agent audit paths")
    parser.add_argument("--helper", action="append", help="Repeat for exact helper source paths")
    parser.add_argument("--artifact", required=True, help="Exact evidence JSON destination")
    parser.add_argument("--appendix", help="Compact Markdown destination; otherwise print it")
    options = parser.parse_args()
    journal_path = job_path(options.journal)
    journal = json.loads(journal_path.read_text(encoding="utf-8"))
    audit_paths = [job_path(path) for path in options.audit] if options.audit else sorted(
        job_path("sf-nr-b1").glob("audit-*.md"))
    helper_paths = [job_path(path) for path in options.helper] if options.helper else sorted(
        job_path("sf-nr-b1").glob("*.py"))
    audits = [{"path": relative(path), "markdown": path.read_text(encoding="utf-8")}
              for path in audit_paths]
    helpers = [{"path": relative(path), "source": path.read_text(encoding="utf-8")}
               for path in helper_paths]
    records, unattached = normalize_journal(journal)
    if not records:
        raise SystemExit("No shell commands recognized; inspect journal schema before generating evidence.")
    artifact_path = job_path(options.artifact)
    artifact = {"format_version": 1, "journal_source": relative(journal_path),
                "root_journal": journal, "root_commands": records,
                "unattached_tool_events": unattached,
                "agent_audits": audits, "helper_sources": helpers}
    appendix = make_appendix(artifact_path, records, audits, unattached)
    write_text(artifact_path, json.dumps(artifact, indent=2, ensure_ascii=False) + "\n")
    if options.appendix:
        write_text(job_path(options.appendix), appendix)
        print(f"Wrote {relative(artifact_path)} and {options.appendix}; "
              f"{len(records)} shell commands, {len(audits)} audits, {len(helpers)} helpers.")
    else:
        print(appendix, end="")


if __name__ == "__main__":
    main()
